import startHandler from "@tanstack/react-start/server-entry";

import { handleRootOAuthAuthorizationServerMetadata } from "./server/metadata";
import { handleQueue, handleScheduled } from "./worker-events";

const worker = {
  async fetch(request: Request, env: Env) {
    const metadataResponse = await handleRootOAuthAuthorizationServerMetadata(request, env);
    return metadataResponse ?? startHandler.fetch(request);
  },

  queue(batch: MessageBatch<unknown>) {
    handleQueue(batch);
  },

  async scheduled(controller: ScheduledController, env: Env) {
    await handleScheduled(controller, env);
  },
};

export default worker;

--- events ---
import { expireStaleInvitations } from "./server/modules/invitations/service";

export function handleQueue(batch: MessageBatch<unknown>) {
  for (const message of batch.messages) message.ack();
}

export async function handleScheduled(
  controller: ScheduledController,
  environment?: Pick<Env, "DB">,
) {
  if (environment) await expireStaleInvitations(environment.DB);
  console.info(JSON.stringify({ cron: controller.cron, message: "shui scheduled probe" }));
}

